PRAGMA foreign_keys=ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')), created_at INTEGER NOT NULL);
CREATE TABLE login_tokens (hash TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE, expires_at INTEGER NOT NULL);
CREATE TABLE sessions (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE study_locks (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, session_hash TEXT NOT NULL REFERENCES sessions(hash) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE courses (id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT '', instructor TEXT NOT NULL DEFAULT '', price REAL NOT NULL DEFAULT 0 CHECK(price>=0), objectives TEXT NOT NULL DEFAULT '[]', extra TEXT NOT NULL DEFAULT '', cover_id TEXT, preview_id TEXT, preview_description TEXT NOT NULL DEFAULT '', preview_visible INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0, deleted_at INTEGER, updated_at INTEGER NOT NULL, updated_by TEXT REFERENCES users(id));
CREATE TABLE sections (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), title TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, layout TEXT NOT NULL DEFAULT 'vertical', width TEXT NOT NULL DEFAULT 'full', collapsed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX sections_course ON sections(course_id,position);
CREATE TABLE media (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, object_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', upload_id TEXT, uploaded_by TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE INDEX media_course ON media(course_id);
CREATE TABLE content_items (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), section_id TEXT NOT NULL REFERENCES sections(id), title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('text','pdf','docx','video','audio','link','heading','divider','quiz')), body TEXT NOT NULL DEFAULT '', media_id TEXT REFERENCES media(id), external_url TEXT, position INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0, direction TEXT NOT NULL DEFAULT 'rtl', width TEXT NOT NULL DEFAULT 'full', updated_at INTEGER NOT NULL);
CREATE INDEX items_course ON content_items(course_id,section_id,position);
CREATE TABLE enrollment_requests (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), email TEXT NOT NULL COLLATE NOCASE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','cancelled')), admin_note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(course_id,email));
CREATE INDEX requests_email ON enrollment_requests(email);
CREATE TABLE grants (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), email TEXT NOT NULL COLLATE NOCASE, active INTEGER NOT NULL DEFAULT 1, granted_at INTEGER NOT NULL, revoked_at INTEGER, granted_by TEXT NOT NULL REFERENCES users(id), UNIQUE(course_id,email));
CREATE INDEX grants_email ON grants(email,active);
CREATE TABLE notes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id TEXT REFERENCES courses(id), item_id TEXT REFERENCES content_items(id) ON DELETE SET NULL, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX notes_owner ON notes(user_id,updated_at);
CREATE TABLE progress (user_id TEXT NOT NULL REFERENCES users(id), item_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE, position REAL NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY(user_id,item_id));
CREATE TABLE quizzes (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), item_id TEXT UNIQUE REFERENCES content_items(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', questions TEXT NOT NULL DEFAULT '[]', max_attempts INTEGER NOT NULL DEFAULT 3, duration_minutes INTEGER NOT NULL DEFAULT 0, shuffle INTEGER NOT NULL DEFAULT 0, explanation_mode TEXT NOT NULL DEFAULT 'after_submit', published INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE TABLE attempts (id TEXT PRIMARY KEY, quiz_id TEXT NOT NULL REFERENCES quizzes(id), user_id TEXT NOT NULL REFERENCES users(id), snapshot TEXT NOT NULL, answers TEXT NOT NULL DEFAULT '{}', result TEXT, score REAL, total REAL, state TEXT NOT NULL DEFAULT 'running', started_at INTEGER NOT NULL, deadline INTEGER, submitted_at INTEGER);
CREATE INDEX attempts_quiz_user ON attempts(quiz_id,user_id,state);
CREATE UNIQUE INDEX one_running_attempt ON attempts(quiz_id,user_id) WHERE state='running';
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), platform_name TEXT NOT NULL DEFAULT 'BayMed', tagline TEXT NOT NULL DEFAULT 'معرفة طبية تُبنى بفهم.', about TEXT NOT NULL DEFAULT 'منصة تعليمية مستقلة لطلاب الطب الجامعي، تجمع المحتوى الدراسي والمراجعة والملاحظات في مساحة واحدة.', contact_email TEXT NOT NULL DEFAULT '', watermark INTEGER NOT NULL DEFAULT 1, copy_notice INTEGER NOT NULL DEFAULT 1);
INSERT INTO settings(id) VALUES(1);
CREATE TABLE contact_messages (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, message TEXT NOT NULL, created_at INTEGER NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
